/* OCR GCSE Computer Science (J277) — grade-separated exam-style questions.
   Each question: { g: grade 4-9, marks, q, scheme: [mark points], answer } */
export default {
  subjectId: "computer-science",
  sections: {
    "Component 1: Computer systems": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What does CPU stand for?", scheme: ["Central Processing Unit"], answer: "Central Processing Unit." },
      { g: 4, marks: 1, q: "What is the main job of the CPU?", scheme: ["To process/carry out instructions (fetch, decode, execute)"], answer: "To fetch, decode and execute the instructions of a program." },
      { g: 4, marks: 1, q: "Name the three stages of the fetch–decode–execute cycle.", scheme: ["Fetch, decode, execute"], answer: "Fetch, decode and execute." },
      { g: 4, marks: 1, q: "What does RAM stand for?", scheme: ["Random Access Memory"], answer: "Random Access Memory." },
      { g: 4, marks: 1, q: "Is RAM volatile or non-volatile?", scheme: ["Volatile (loses its contents when the power is off)"], answer: "Volatile — it loses its contents when the power is switched off." },
      { g: 4, marks: 1, q: "What does ROM stand for and what is it used for?", scheme: ["Read Only Memory; stores the boot/start-up instructions"], answer: "Read Only Memory — it stores the start-up (boot) instructions." },
      { g: 4, marks: 1, q: "Give one example of secondary storage.", scheme: ["HDD / SSD / optical disc / magnetic tape / USB flash drive (any one)"], answer: "A hard disk drive (or SSD, optical disc, USB flash drive)." },
      { g: 4, marks: 1, q: "How many bits are there in a byte?", scheme: ["8"], answer: "8 bits." },
      { g: 4, marks: 1, q: "What is a LAN?", scheme: ["Local Area Network — covers a small geographical area"], answer: "A Local Area Network, covering a small area such as a building or site." },
      { g: 4, marks: 1, q: "What is a WAN?", scheme: ["Wide Area Network — covers a large geographical area (e.g. the internet)"], answer: "A Wide Area Network, covering a large geographical area, such as the internet." },
      { g: 4, marks: 1, q: "What is malware?", scheme: ["Malicious software (designed to harm/gain access)"], answer: "Malicious software designed to damage or gain unauthorised access to a computer." },
      { g: 4, marks: 1, q: "What is the number base of binary?", scheme: ["Base 2"], answer: "Base 2." },
      { g: 4, marks: 1, q: "What is the number base of hexadecimal?", scheme: ["Base 16"], answer: "Base 16." },
      { g: 4, marks: 1, q: "What is a network protocol?", scheme: ["A set of rules for communication/data transfer"], answer: "A set of rules that governs how data is transmitted between devices." },
      { g: 4, marks: 1, q: "State the job of the operating system in one sentence.", scheme: ["Manages the hardware, software and resources of the computer"], answer: "It manages the computer's hardware, software and resources." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "Define 'clock speed'.", scheme: ["The number of fetch–decode–execute cycles per second (measured in Hz)"], answer: "The number of instruction cycles the CPU carries out per second, measured in hertz (Hz)." },
      { g: 5, marks: 2, q: "State two differences between RAM and ROM.", scheme: ["RAM is volatile; ROM is non-volatile", "RAM can be read/written; ROM is read-only (stores boot instructions)"], answer: "RAM is volatile and can be read from and written to, holding running programs; ROM is non-volatile and read-only, storing the boot instructions." },
      { g: 5, marks: 1, q: "What does cache memory do?", scheme: ["Stores frequently used data/instructions close to the CPU for faster access"], answer: "It stores frequently used data and instructions close to the CPU so they can be accessed quickly." },
      { g: 5, marks: 1, q: "What is virtual memory?", scheme: ["Using secondary storage as extra RAM when RAM is full"], answer: "Using part of the secondary storage as extra RAM when the RAM is full." },
      { g: 5, marks: 2, q: "Convert the binary number 1010 into denary.", scheme: ["8 + 0 + 2 + 0", "= 10"], answer: "8 + 2 = 10." },
      { g: 5, marks: 1, q: "What is the role of DNS?", scheme: ["Translates domain names into IP addresses"], answer: "It translates domain names (like a website address) into IP addresses." },
      { g: 5, marks: 2, q: "Name two network topologies.", scheme: ["Any two: star, mesh (also bus, ring)"], answer: "Star and mesh topologies." },
      { g: 5, marks: 2, q: "Name two types of malware.", scheme: ["Any two: virus, worm, trojan, ransomware, spyware"], answer: "A virus and ransomware (also worms, trojans, spyware)." },
      { g: 5, marks: 1, q: "What is phishing?", scheme: ["Fraudulent emails/messages that trick users into revealing personal information"], answer: "Sending fake emails or messages to trick people into revealing personal information such as passwords." },
      { g: 5, marks: 1, q: "What is utility software? Give an example.", scheme: ["Software that maintains/manages the computer, e.g. defragmentation, backup, antivirus"], answer: "Software that helps maintain the computer, such as backup or disk defragmentation software." },
      { g: 5, marks: 1, q: "What is an embedded system?", scheme: ["A computer built into a device to perform a specific/dedicated function"], answer: "A computer built into a larger device to carry out one specific function, such as in a washing machine." },
      { g: 5, marks: 2, q: "Put these storage units in order, smallest first: MB, byte, GB, KB.", scheme: ["byte, KB, MB, GB"], answer: "byte, KB, MB, GB." },
      { g: 5, marks: 1, q: "What is the difference between lossy and lossless compression?", scheme: ["Lossy permanently removes data; lossless keeps all data (reversible)"], answer: "Lossy compression permanently removes some data, while lossless compression keeps all the data so the original can be restored." },
      { g: 5, marks: 1, q: "State two characteristics of the CPU that affect its performance.", scheme: ["Any two: clock speed, number of cores, cache size"], answer: "Clock speed and the number of cores (also cache size)." },
      { g: 5, marks: 1, q: "What does a firewall do?", scheme: ["Monitors/filters network traffic (in and out) based on rules"], answer: "It monitors and filters the traffic coming into and out of a network based on rules." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 3, q: "Describe the fetch–decode–execute cycle.", scheme: ["Fetch: the next instruction is copied from memory to the CPU", "Decode: the control unit works out what the instruction means", "Execute: the instruction is carried out; the cycle then repeats"], answer: "The CPU fetches the next instruction from memory, the control unit decodes it to work out what to do, and then the instruction is executed. The cycle then repeats." },
      { g: 6, marks: 2, q: "Explain how increasing the clock speed improves CPU performance.", scheme: ["More fetch–decode–execute cycles per second", "So more instructions are processed each second"], answer: "A higher clock speed means more fetch–decode–execute cycles are carried out each second, so more instructions are processed." },
      { g: 6, marks: 2, q: "Explain why cache memory speeds up processing.", scheme: ["Frequently used data/instructions are stored close to the CPU", "Faster to access than fetching from RAM, so fewer slow fetches"], answer: "Cache stores frequently used data and instructions close to the CPU, so they are accessed faster than fetching from RAM, reducing waiting time." },
      { g: 6, marks: 3, q: "Compare SSDs and HDDs.", scheme: ["SSD: no moving parts, faster, more durable/shock-proof, but more expensive per GB", "HDD: cheaper per GB, larger capacities, but slower and has moving parts"], answer: "SSDs have no moving parts, so they are faster and more durable but cost more per gigabyte; HDDs are cheaper with larger capacities but are slower and can be damaged by movement." },
      { g: 6, marks: 2, q: "Convert the denary number 45 into binary.", scheme: ["32 + 8 + 4 + 1", "= 101101"], answer: "45 = 32 + 8 + 4 + 1 = 101101." },
      { g: 6, marks: 2, q: "Convert the binary number 11110000 into hexadecimal.", scheme: ["1111 = F; 0000 = 0", "= F0"], answer: "Split into nibbles: 1111 = F and 0000 = 0, so it is F0." },
      { g: 6, marks: 2, q: "Explain how virtual memory works and give one drawback.", scheme: ["When RAM is full, data is moved to a page file on secondary storage", "Drawback: slower because disk access is slower than RAM"], answer: "When the RAM is full, less-used data is moved to a page file on the secondary storage to free up RAM. The drawback is that this is slower because reading from disk is slower than from RAM." },
      { g: 6, marks: 2, q: "Explain one advantage of a star topology.", scheme: ["Each device connects to a central switch", "If one cable fails, the other devices are unaffected"], answer: "In a star topology every device has its own cable to a central switch, so if one cable fails only that device is affected, not the rest of the network." },
      { g: 6, marks: 2, q: "Explain why protocols are needed on a network.", scheme: ["They are agreed rules for communication", "So devices from different manufacturers can communicate reliably"], answer: "Protocols are agreed sets of rules for communication, so that devices made by different manufacturers can exchange data reliably." },
      { g: 6, marks: 2, q: "Explain what 'social engineering' means, with an example.", scheme: ["Manipulating/tricking people into giving away information or access", "Example: phishing / pretexting / baiting"], answer: "Social engineering is tricking people into giving away confidential information or access, for example through a phishing email pretending to be from a bank." },
      { g: 6, marks: 2, q: "Explain how an image is represented in binary.", scheme: ["The image is split into pixels", "Each pixel is given a binary code for its colour (plus metadata like size/resolution)"], answer: "An image is divided into pixels, and each pixel is stored as a binary code representing its colour, along with metadata such as the image's dimensions." },
      { g: 6, marks: 2, q: "Explain the role of the MAR and MDR registers.", scheme: ["MAR (Memory Address Register) holds the address to be read from or written to", "MDR (Memory Data Register) holds the data being transferred to/from memory"], answer: "The MAR holds the memory address that is to be read from or written to, and the MDR holds the actual data being transferred to or from that address." },
      { g: 6, marks: 2, q: "Explain how a firewall helps protect a network.", scheme: ["Examines incoming and outgoing traffic (data packets)", "Blocks anything that doesn't meet the security rules"], answer: "A firewall examines the data packets coming into and going out of a network and blocks any traffic that does not meet its security rules." },
      { g: 6, marks: 2, q: "Explain the difference between the internet and the World Wide Web.", scheme: ["The internet is the global network of connected computers (infrastructure)", "The World Wide Web is a service of web pages accessed over the internet"], answer: "The internet is the global network of connected computers, while the World Wide Web is a service of interlinked web pages that is accessed using the internet." },
      { g: 6, marks: 2, q: "Explain why encryption protects data even if it is intercepted.", scheme: ["The data is scrambled into an unreadable form", "It cannot be understood without the decryption key"], answer: "Encryption scrambles the data so that even if it is intercepted it is meaningless without the correct decryption key." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Explain how the characteristics of a CPU (clock speed, number of cores and cache) affect its performance.", scheme: ["Higher clock speed → more cycles/second → more instructions processed", "More cores → more instructions processed at the same time (parallel)", "More/larger cache → more frequently used data near the CPU → fewer slow fetches", "Together they can improve overall performance"], answer: "A higher clock speed means more instruction cycles per second, and more cores allow several instructions to be processed at once. A larger cache keeps more frequently used data close to the CPU, reducing slow fetches from RAM. Together these characteristics improve performance." },
      { g: 7, marks: 3, q: "Convert the denary number 200 into binary and then into hexadecimal.", scheme: ["200 = 11001000 in binary", "1100 = C, 1000 = 8", "= C8"], answer: "200 = 128 + 64 + 8 = 11001000 in binary. Splitting into nibbles: 1100 = C and 1000 = 8, so it is C8 in hex." },
      { g: 7, marks: 3, q: "Add the binary numbers 1011 and 0110, showing your working.", scheme: ["1011 + 0110", "Carry handled correctly", "= 10001"], answer: "1011 + 0110 = 10001 (11 + 6 = 17), with a carry into the fifth column." },
      { g: 7, marks: 3, q: "An image is 10 pixels by 10 pixels and uses 3 bits per pixel. Calculate the file size in bits and in bytes.", scheme: ["10 × 10 = 100 pixels", "100 × 3 = 300 bits", "300 ÷ 8 = 37.5 bytes"], answer: "There are 10 × 10 = 100 pixels, each using 3 bits, so 100 × 3 = 300 bits, which is 300 ÷ 8 = 37.5 bytes." },
      { g: 7, marks: 3, q: "Explain how a message is sent from one computer to another as packets.", scheme: ["The data is split into small packets", "Each packet has a header (e.g. destination address, order number)", "Packets are routed across the network and reassembled in order at the destination"], answer: "The data is split into small packets, each given a header containing information such as the destination address and its order. The packets are routed across the network and reassembled in the correct order at the destination." },
      { g: 7, marks: 3, q: "Explain how the number of bits used for a character set affects how many characters can be represented, using ASCII and Unicode.", scheme: ["n bits can represent 2^n different values", "ASCII uses 7 bits → 128 characters", "Unicode uses more bits → many more characters (all languages/symbols)"], answer: "With n bits you can represent 2^n characters. ASCII uses 7 bits, giving 128 characters, whereas Unicode uses more bits so it can represent far more characters, including those of many languages and symbols." },
      { g: 7, marks: 3, q: "Explain step by step how DNS is used when a user types a web address into a browser.", scheme: ["The browser sends the domain name to a DNS server", "The DNS server looks up and returns the matching IP address", "The browser uses the IP address to connect to the web server"], answer: "The browser sends the domain name to a DNS server, which looks it up and returns the matching IP address. The browser then uses that IP address to connect to the correct web server." },
      { g: 7, marks: 3, q: "Explain two methods of preventing network attacks and how each works.", scheme: ["Any two: firewall filters traffic; encryption scrambles data; anti-malware detects/removes; strong passwords/authentication; user access levels", "Each with a brief explanation of how it works"], answer: "A firewall filters incoming and outgoing traffic to block unauthorised access, and encryption scrambles data so it is useless if intercepted. Anti-malware software could also be used to detect and remove malicious programs." },
      { g: 7, marks: 3, q: "Explain the role of utility software, giving two examples.", scheme: ["Helps maintain and manage the computer system", "Example 1: disk defragmentation reorganises fragmented files", "Example 2: backup copies data so it can be restored"], answer: "Utility software maintains and manages the system. For example, disk defragmentation reorganises fragmented files so they can be accessed faster, and backup software copies data so it can be restored if lost." },
      { g: 7, marks: 3, q: "Convert the hexadecimal number 2F into denary, showing your working.", scheme: ["2 × 16 = 32", "F = 15", "32 + 15 = 47"], answer: "2 × 16 = 32 and F = 15, so 32 + 15 = 47." },
      { g: 7, marks: 3, q: "Explain how sound is converted into binary and state what affects the file size.", scheme: ["The sound wave is sampled at regular intervals (analogue to digital)", "Each sample is stored as a binary value", "File size depends on the sample rate and bit depth (and length)"], answer: "The analogue sound wave is sampled at regular intervals and each sample is stored as a binary value. The file size depends on the sample rate, the bit depth and the length of the recording." },
      { g: 7, marks: 3, q: "Explain why a computer might slow down when many programs are open, referring to memory.", scheme: ["The RAM fills up with the open programs' data", "Virtual memory is used, moving data to the slower disk", "Constant swapping between RAM and disk slows the computer"], answer: "As many programs are opened the RAM fills up, so the system uses virtual memory and moves data to the slower disk. Constantly swapping data between RAM and disk slows the computer down." },
      { g: 7, marks: 2, q: "Explain the difference between a switch and a router.", scheme: ["A switch connects devices within a single (local) network and directs data to the correct device", "A router connects different networks together and directs data between them (e.g. to the internet)"], answer: "A switch connects devices within one network and sends data to the correct device, while a router connects different networks together and directs data between them, such as connecting a home network to the internet." },
      { g: 7, marks: 3, q: "Explain how anti-malware software helps keep a computer secure.", scheme: ["Scans files/programs for known malware signatures/behaviour", "Detects and quarantines or removes malicious software", "Can be updated to detect new threats"], answer: "Anti-malware software scans files and programs for known malicious code or suspicious behaviour, then quarantines or removes anything it finds, and is regularly updated so it can detect new threats." },
      { g: 7, marks: 3, q: "Explain two ways an operating system manages the hardware of a computer.", scheme: ["Manages memory (allocates RAM to programs)", "Manages peripherals/devices (via drivers)", "Manages processes/the CPU (scheduling) (any two)"], answer: "The operating system manages memory by allocating RAM to running programs, and manages peripherals using device drivers so hardware such as printers works correctly." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Explain the fetch–decode–execute cycle, including the roles of the Program Counter (PC), MAR, MDR and Accumulator.", scheme: ["PC holds the address of the next instruction; it is copied to the MAR", "The instruction at that address is fetched into the MDR (PC increments)", "The instruction is decoded by the control unit", "It is executed; results of calculations are held in the accumulator"], answer: "The Program Counter holds the address of the next instruction, which is copied to the MAR. The instruction at that address is fetched into the MDR and the PC is incremented. The control unit then decodes the instruction and it is executed, with the results of any calculations stored in the accumulator." },
      { g: 8, marks: 4, q: "A user needs storage for a laptop they carry around. Evaluate whether an SSD or HDD is more suitable.", scheme: ["SSD: faster, no moving parts so durable/shock-resistant, lighter, silent, less power", "HDD: cheaper per GB, larger capacity", "For a portable laptop durability/speed/weight matter", "Justified choice: SSD is usually more suitable"], answer: "An SSD is faster, has no moving parts so it resists knocks, is lighter, silent and uses less power, whereas an HDD is cheaper with larger capacity but is fragile and slower. Because the laptop is carried around, durability, speed and weight matter most, so an SSD is the more suitable choice." },
      { g: 8, marks: 4, q: "Explain how compression reduces file size and evaluate lossy versus lossless for storing music and text.", scheme: ["Compression reduces the number of bits needed to store a file", "Lossy removes data the user is less likely to notice → much smaller, not reversible", "Lossless keeps all data → reversible but larger", "Music can use lossy (small, quality acceptable); text needs lossless (no data can be lost)"], answer: "Compression reduces the number of bits needed to store a file. Lossy compression removes data that is less noticeable, giving much smaller files but permanent loss, while lossless keeps all the data so the original can be restored but files are larger. Music can use lossy compression as small quality losses are acceptable, but text must use lossless because losing characters would corrupt it." },
      { g: 8, marks: 4, q: "Explain how a firewall and encryption together help protect data on a network.", scheme: ["Firewall controls access — blocks unauthorised traffic entering/leaving", "Reduces the chance of attackers reaching the data", "Encryption scrambles the data so intercepted data is unreadable", "Together they protect against access AND interception"], answer: "A firewall controls access by blocking unauthorised traffic entering or leaving the network, reducing the chance of attackers reaching the data. Encryption then scrambles the data so that anything intercepted is unreadable without the key. Together they protect against both unauthorised access and interception." },
      { g: 8, marks: 3, q: "Explain the effect of increasing the sample rate and bit depth of a sound recording on its quality and file size.", scheme: ["Higher sample rate → more samples per second → more accurate sound → larger file", "Higher bit depth → more detail per sample → better quality → larger file", "Both improve quality but increase file size"], answer: "A higher sample rate takes more samples each second, giving a more accurate recording, and a higher bit depth stores more detail per sample, improving quality. Both improve the sound quality but also increase the file size." },
      { g: 8, marks: 4, q: "Analyse how clock speed, cores and cache each affect performance, including any trade-offs.", scheme: ["Clock speed: faster cycles, but higher heat/power use", "Cores: parallel processing, but only helps software written to use multiple cores", "Cache: fast local storage, but is expensive and limited in size", "Overall performance depends on the balance and the task"], answer: "A higher clock speed processes instructions faster but produces more heat and uses more power. More cores allow parallel processing, but only benefit software written to use them. A larger cache reduces slow RAM fetches but is expensive and limited in size. Overall performance depends on balancing these and on the type of task." },
      { g: 8, marks: 3, q: "Explain how virtual memory allows more programs to run than the RAM alone could hold, and its performance cost.", scheme: ["Data not currently needed is moved from RAM to a page file on disk", "This frees RAM for other programs, so more can be open", "Performance cost: disk is much slower, and swapping data (thrashing) slows the system"], answer: "Virtual memory moves data that isn't currently needed from RAM to a page file on the disk, freeing RAM so more programs can run. The cost is that the disk is far slower than RAM, so frequently swapping data back and forth slows the computer down." },
      { g: 8, marks: 3, q: "Analyse one ethical and one legal issue raised by companies collecting large amounts of user data.", scheme: ["Ethical: privacy — users may not know how their data is used/shared", "Legal: data protection law requires data to be stored securely and used lawfully", "Consequences if misused (harm to users / fines)"], answer: "An ethical issue is privacy, as users may not realise how much data is collected or how it is shared. A legal issue is that data protection law requires the data to be stored securely and used lawfully, and companies can be fined if they misuse it or fail to protect it." },
      { g: 8, marks: 4, q: "Explain how the TCP/IP protocols are used to send data across the internet.", scheme: ["TCP splits data into packets and reassembles them, checking for errors/order", "IP addresses and routes the packets to the correct destination", "Packets may take different routes and are reassembled at the end", "Together they ensure reliable delivery"], answer: "TCP splits the data into packets, numbers them and reassembles them in order at the destination, checking for errors, while IP handles addressing and routing the packets to the correct destination. The packets may travel different routes and are reassembled at the end, so together they deliver the data reliably." },
      { g: 8, marks: 3, q: "Evaluate wired versus wireless connections for a home network.", scheme: ["Wired: faster, more reliable/secure, but needs cables (less convenient)", "Wireless: convenient, mobile, no cables, but can be slower/less secure/affected by interference", "Justified conclusion based on needs"], answer: "Wired connections are usually faster, more reliable and more secure but need cables running to each device, while wireless is convenient and lets devices move freely but can be slower, less secure and affected by interference. For a home where convenience matters most, wireless is often chosen, with wired used where speed and reliability are important." },
      { g: 8, marks: 3, q: "Explain how one type of malware works and describe a measure that would counter it.", scheme: ["Named malware and how it works (e.g. ransomware encrypts files and demands payment)", "A counter measure (e.g. regular backups so files can be restored)", "Explanation of how the measure helps"], answer: "Ransomware encrypts a victim's files and demands payment for the decryption key. Keeping regular backups counters this, because the files can be restored from the backup without paying the attacker." },
      { g: 8, marks: 3, q: "Explain the environmental impacts of computer technology and one way they can be reduced.", scheme: ["Impacts: energy use, e-waste, use of resources in manufacturing", "A reduction method: recycling devices, energy-efficient hardware, longer device lifespans", "Explanation of the benefit"], answer: "Computing uses large amounts of energy and creates electronic waste and uses resources in manufacturing. This can be reduced by recycling old devices and using energy-efficient hardware, which cuts waste and energy consumption." },
      { g: 8, marks: 4, q: "Convert the denary number 173 into 8-bit binary and into hexadecimal, showing your working.", scheme: ["173 = 128 + 32 + 8 + 4 + 1 = 10101101", "1010 = A, 1101 = D", "= AD"], answer: "173 = 128 + 32 + 8 + 4 + 1 = 10101101. Splitting into nibbles: 1010 = A and 1101 = D, so it is AD in hexadecimal." },
      { g: 8, marks: 3, q: "Explain how the operating system manages several programs running at the same time.", scheme: ["It schedules processes, giving each CPU time in turn", "It allocates memory to each program and prevents them interfering", "This makes it appear that programs run simultaneously"], answer: "The operating system schedules the running programs, giving each a share of CPU time in turn, and allocates separate memory to each so they don't interfere. This rapid switching makes it appear that the programs run at the same time." },
      { g: 8, marks: 3, q: "Explain why hexadecimal is often used by programmers instead of binary.", scheme: ["Hex is shorter than binary (1 hex digit = 4 bits)", "Easier for humans to read and less error-prone", "Easy to convert to/from binary"], answer: "Hexadecimal is much shorter than binary because one hex digit represents four bits, so it is easier for programmers to read and write and less error-prone, while still converting easily to and from binary." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Explain fully how the CPU executes a program, referring to the fetch–decode–execute cycle, the registers used, and the factors that affect how quickly it runs.", scheme: ["PC holds address of next instruction → copied to MAR", "Instruction fetched into MDR; PC incremented", "Control unit decodes the instruction", "ALU executes it; results held in the accumulator", "Cycle repeats for each instruction", "Speed affected by clock speed, cores and cache size"], answer: "The Program Counter holds the address of the next instruction, which is copied to the MAR; the instruction is fetched into the MDR and the PC is incremented. The control unit decodes it, and the ALU executes it, holding any results in the accumulator, before the cycle repeats. How quickly this runs depends on the clock speed, the number of cores and the size of the cache." },
      { g: 9, marks: 6, q: "Explain how text, images and sound are each represented in binary, and how compression can be applied, evaluating the trade-offs.", scheme: ["Text: each character stored as a binary code (ASCII/Unicode)", "Image: pixels each stored as a colour value + metadata", "Sound: wave sampled; each sample stored as binary (sample rate/bit depth)", "Lossy compression: smaller files, permanent loss", "Lossless: reversible but larger", "Trade-off between file size and quality/accuracy"], answer: "Text is stored as a binary code for each character using ASCII or Unicode; an image is stored as pixels, each with a binary colour value plus metadata; and sound is sampled and each sample stored as a binary value, set by the sample rate and bit depth. Lossy compression makes files much smaller but loses data permanently, while lossless is reversible but larger, so there is a trade-off between file size and quality." },
      { g: 9, marks: 6, q: "A small business is setting up a network. Explain the threats it faces and recommend, with justification, measures to keep the network secure.", scheme: ["Threats: malware, phishing/social engineering, unauthorised access, data interception", "Firewall to control access", "Anti-malware software, kept updated", "Encryption of sensitive data", "Strong passwords/authentication and user access levels", "Staff training against social engineering; justified choices"], answer: "The business faces threats such as malware, phishing and social engineering, unauthorised access and data interception. To defend against these it should use a firewall to control traffic, updated anti-malware software, and encryption for sensitive data, along with strong passwords, user access levels and staff training to resist phishing. Together these protect against both technical attacks and human manipulation." },
      { g: 9, marks: 6, q: "Explain how a web page is delivered to a user, from typing the URL to it displaying, including DNS, IP addressing, packets and protocols.", scheme: ["Browser sends the domain name to a DNS server → returns the IP address", "Browser sends a request to the web server at that IP", "Data is split into packets (TCP) and addressed/routed (IP)", "Packets may take different routes across the internet", "Reassembled in order at the browser; errors handled", "The page is then rendered/displayed"], answer: "When the user types the URL, the browser sends the domain name to a DNS server, which returns the site's IP address. The browser requests the page from the web server at that IP. The data is split into packets by TCP and addressed and routed by IP, and the packets may take different routes across the internet before being reassembled in order at the browser, which then renders the page." },
      { g: 9, marks: 6, q: "Evaluate the choice of secondary storage for a system that stores a very large video archive that is rarely accessed.", scheme: ["Options: HDD, SSD, magnetic tape, optical", "Rarely accessed → speed matters less; capacity and cost per GB matter most", "Magnetic tape: very cheap per GB, huge capacity, good for archives, but slow/sequential access", "HDD: cheaper than SSD, large capacity, reasonable access", "SSD: fast but expensive — not needed here", "Justified recommendation (tape or HDD)"], answer: "As the archive is huge but rarely accessed, capacity and cost per gigabyte matter far more than speed. Magnetic tape is very cheap per gigabyte with huge capacity, making it ideal for archiving despite slow sequential access, while HDDs are a reasonable alternative offering large, cheaper storage with better access. An expensive fast SSD is unnecessary here, so magnetic tape (or HDD) is the best choice." },
      { g: 9, marks: 6, q: "Analyse the trade-offs a manufacturer must consider when designing a CPU with more cores versus a higher clock speed.", scheme: ["More cores: parallel processing, good for multitasking/multi-threaded software", "But only helps if software is written to use multiple cores; more complex/expensive; heat", "Higher clock speed: faster single-thread performance", "But more heat and power; limits from cooling", "Best design depends on the intended tasks", "Balanced conclusion"], answer: "More cores allow parallel processing, which suits multitasking and multi-threaded software, but only help if the software is written to use them and add cost, complexity and heat. A higher clock speed improves single-task performance but generates more heat and uses more power, limited by cooling. The best design therefore depends on the intended tasks, so manufacturers balance the two." },
      { g: 9, marks: 6, q: "Evaluate the ethical, legal, cultural and environmental impacts of the widespread use of smartphones.", scheme: ["Ethical: privacy, screen addiction, data collection", "Legal: data protection, copyright, laws on use (e.g. driving)", "Cultural: changed communication/social behaviour, access to information", "Environmental: energy, e-waste, resource mining", "Balanced points across at least three areas", "Justified overall judgement"], answer: "Smartphones raise ethical concerns such as privacy and data collection, legal issues like data protection and copyright, and cultural effects as they change how people communicate and access information. Environmentally, they use energy and rare resources and create e-waste. On balance they bring great benefits but need responsible use, regulation and recycling to reduce the harms." },
      { g: 9, marks: 5, q: "Explain fully how virtual memory works and evaluate it as a solution to limited RAM.", scheme: ["When RAM is full, less-used data is moved to a page file on secondary storage", "This frees RAM so more programs can run", "Data is swapped back to RAM when needed", "Advantage: allows more/larger programs than RAM alone", "Disadvantage: disk is slow; excessive swapping (thrashing) slows the system", "Conclusion: useful stop-gap but adding real RAM is better"], answer: "Virtual memory moves less-used data from RAM to a page file on secondary storage, freeing RAM so more programs can run, and swaps the data back when needed. Its advantage is allowing more or larger programs than the RAM alone could hold, but the disk is far slower, so heavy swapping (thrashing) slows the system. It is a useful stop-gap, but adding more real RAM is a better long-term solution." },
      { g: 9, marks: 6, q: "Explain how the operating system and utility software work together to keep a computer running efficiently and securely.", scheme: ["OS manages memory, processes, peripherals and user interface", "OS manages security (user accounts, access rights)", "Utility software maintains the system: defragmentation, backup, compression", "Anti-malware/encryption utilities improve security", "Together they keep the system efficient and protected", "Clear links between roles"], answer: "The operating system manages memory, processes, peripherals and the user interface, and controls security through user accounts and access rights. Utility software supports this by maintaining the system — defragmenting disks, backing up and compressing files — while anti-malware and encryption utilities improve security. Working together, they keep the computer efficient and protected." },
      { g: 9, marks: 5, q: "A company is deciding between a wired and a wireless network for a busy office. Evaluate the options and make a justified recommendation.", scheme: ["Wired: faster, more reliable, more secure; but costly to install cables, less flexible", "Wireless: flexible, cheaper to install, supports mobile devices; but slower, interference, security risks", "Busy office may need reliability/speed and support for many/mobile devices", "Possible hybrid solution", "Justified recommendation"], answer: "A wired network is faster, more reliable and more secure but is costly to install and inflexible, while wireless is cheaper to set up and supports mobile devices but can be slower, suffer interference and pose security risks. A busy office needs both reliability and support for many, often mobile, devices, so the best recommendation is usually a hybrid — wired connections for fixed high-demand computers and secured wireless for mobile devices." },
      { g: 9, marks: 5, q: "Explain how encryption keeps data secure and evaluate its importance using an example such as online banking.", scheme: ["Data is scrambled using a key so it is unreadable without the key", "Intercepted data is meaningless to attackers", "In online banking it protects login and financial details in transit", "Very important where sensitive data is sent over networks", "Limitation: relies on keeping keys secure / strong algorithms"], answer: "Encryption scrambles data using a key so that it is unreadable to anyone without the key, meaning intercepted data is meaningless to attackers. In online banking it protects login and payment details as they travel across the internet, which is vital given how sensitive the data is. Its effectiveness relies on keeping the keys secret and using strong algorithms." },
      { g: 9, marks: 6, q: "Explain the full process and dangers of social engineering, and how an organisation can defend against it.", scheme: ["Social engineering manipulates people rather than technology", "Methods: phishing, pretexting, baiting, shouldering", "Danger: attackers gain passwords/access despite technical security", "Defence: staff training/awareness, verification procedures", "Technical support: spam filters, limiting access rights", "Human factor is often the weakest link"], answer: "Social engineering manipulates people rather than attacking technology, using methods such as phishing emails, pretexting, baiting and shoulder-surfing to trick staff into revealing passwords or access. It is dangerous because it can bypass strong technical security by exploiting the human weakness. Organisations defend against it through staff training and awareness, verification procedures for requests, and technical support such as spam filters and limiting each user's access rights." },
      { g: 9, marks: 5, q: "Compare binary, denary and hexadecimal, and explain why each is used in computing.", scheme: ["Binary (base 2): how computers actually store/process data (on/off)", "Denary (base 10): human everyday counting", "Hexadecimal (base 16): shorthand for binary, shorter and easier to read", "One hex digit = 4 bits", "Each used where it is most convenient"], answer: "Binary (base 2) is how computers physically store and process data using on/off states, denary (base 10) is the system humans count in, and hexadecimal (base 16) is a compact shorthand for binary where one hex digit represents four bits. Hex is used because it is much shorter and easier for programmers to read while converting easily to binary, so each system is used where it is most convenient." },
      { g: 9, marks: 6, q: "Evaluate whether the benefits of cloud storage outweigh the drawbacks for an individual user.", scheme: ["Benefits: access anywhere/any device, automatic backup, no local storage needed, easy sharing", "Drawbacks: needs internet, ongoing cost, privacy/security concerns (data held by a company)", "Reliability depends on the provider", "Weigh convenience against privacy/dependence", "Justified conclusion"], answer: "Cloud storage lets a user access files from anywhere on any device, provides automatic backup, saves local storage and makes sharing easy. However, it needs an internet connection, may cost money over time, and raises privacy and security concerns because the data is held by a company. Whether it is worth it depends on the user, but for most people the convenience and backup benefits outweigh the drawbacks, provided they trust the provider." },
      { g: 9, marks: 5, q: "Explain why an embedded system is used in a device such as a washing machine rather than a general-purpose computer.", scheme: ["Embedded system is dedicated to one specific task", "Cheaper, smaller and uses less power than a general-purpose computer", "More reliable as it runs fixed software", "A general-purpose computer would be unnecessary/expensive/less robust", "Justified reasoning"], answer: "A washing machine uses an embedded system because it only needs to perform one dedicated task, so a small, cheap, low-power and reliable controller running fixed software is ideal. A general-purpose computer would be unnecessarily large, expensive, power-hungry and less robust for such a simple, specific job." },
    ],
    "Component 2: Algorithms & programming": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is meant by abstraction in computational thinking?", scheme: ["Removing unnecessary detail so you can focus on the important parts of a problem"], answer: "Abstraction means removing unnecessary detail from a problem so you can focus only on the parts that matter." },
      { g: 4, marks: 1, q: "What is meant by decomposition?", scheme: ["Breaking a problem down into smaller, more manageable sub-problems"], answer: "Breaking a large problem down into smaller, more manageable sub-problems." },
      { g: 4, marks: 1, q: "Name the three basic programming constructs.", scheme: ["Sequence, selection and iteration"], answer: "Sequence, selection and iteration." },
      { g: 4, marks: 1, q: "What is a variable in a program?", scheme: ["A named memory location that stores a value which can change while the program runs"], answer: "A named location in memory that stores a value which can change while the program is running." },
      { g: 4, marks: 1, q: "What is the result of 17 MOD 5?", scheme: ["2 (the remainder when 17 is divided by 5)"], answer: "2 — MOD gives the remainder, and 17 ÷ 5 = 3 remainder 2." },
      { g: 4, marks: 1, q: "What is the result of 17 DIV 5?", scheme: ["3 (the whole-number part of 17 divided by 5)"], answer: "3 — DIV gives the whole number of times 5 goes into 17." },
      { g: 4, marks: 1, q: "Which data type is most suitable for storing whether a light is switched on or off?", scheme: ["Boolean"], answer: "Boolean (true or false)." },
      { g: 4, marks: 1, q: "What is the output of an AND gate when one input is 1 and the other input is 0?", scheme: ["0"], answer: "0 — an AND gate only outputs 1 when both inputs are 1." },
      { g: 4, marks: 1, q: "What is a syntax error?", scheme: ["An error that breaks the rules (grammar) of the programming language, so the program cannot be translated/run"], answer: "An error that breaks the rules of the programming language, such as a misspelt keyword, which stops the program from being translated and run." },
      { g: 4, marks: 1, q: "Give one example of a high-level programming language.", scheme: ["Python / Java / C# / C++ / Visual Basic (any one)"], answer: "Python (also Java, C#, C++ or Visual Basic)." },
      { g: 4, marks: 2, q: "Name two features of an Integrated Development Environment (IDE).", scheme: ["Any one: editor, error diagnostics (debugging tools), run-time environment, translator", "A second, different feature from the list"], answer: "An editor for writing code and error diagnostics for finding errors (also a run-time environment or a translator)." },
      { g: 4, marks: 2, q: "Name two types of validation check.", scheme: ["Any one: range check, length check, type check, presence check, format check", "A second, different validation check"], answer: "A range check and a presence check (also length, type or format checks)." },
      { g: 4, marks: 1, q: "What must be true about a list before a binary search can be used on it?", scheme: ["It must be sorted (in order)"], answer: "The list must already be sorted into order." },
      { g: 4, marks: 1, q: "What is meant by casting in programming?", scheme: ["Converting data from one data type to another, e.g. using int() or str()"], answer: "Converting data from one data type to another, for example using int() to turn the string \"42\" into the integer 42." },
      { g: 4, marks: 1, q: "What is an array?", scheme: ["A data structure that stores a collection of values of the same data type under one identifier (name)"], answer: "A data structure that stores several values of the same data type under a single name, with each value accessed by its index." },
      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "Explain the difference between a variable and a constant.", scheme: ["A variable's value can change while the program is running", "A constant's value stays the same (cannot be changed) while the program is running"], answer: "The value stored in a variable can change while the program is running, whereas a constant's value is set once and cannot change while the program runs." },
      { g: 5, marks: 2, q: "State the difference between a function and a procedure.", scheme: ["A function returns a value to the part of the program that called it", "A procedure carries out a task but does not return a value"], answer: "A function carries out a task and returns a value to where it was called, whereas a procedure carries out a task without returning a value." },
      { g: 5, marks: 2, q: "Describe how a linear search looks for an item in a list.", scheme: ["It starts at the first item and compares each item with the target in turn", "It stops when the item is found, or when the end of the list is reached (item not found)"], answer: "A linear search starts at the first item and checks each item in turn against the target. It stops when the item is found or when it reaches the end of the list without finding it." },
      { g: 5, marks: 1, q: "Give one advantage of a linear search compared with a binary search.", scheme: ["It works on an unsorted list (also accept: simpler to program / can be quicker for very small lists)"], answer: "A linear search works on an unsorted list, whereas a binary search needs the list to be sorted first." },
      { g: 5, marks: 2, q: "State the most suitable data type for storing:\n(a) the price of an item, such as 4.99\n(b) a phone number, such as 07700900123", scheme: ["(a) Real / float", "(b) String (keeps the leading zero; no calculations are done on it)"], answer: "(a) Real (float), because it has a decimal part. (b) String, because it starts with a zero that must be kept and no calculations are done on it." },
      { g: 5, marks: 2, q: "Explain the difference between a count-controlled loop and a condition-controlled loop.", scheme: ["A count-controlled (for) loop repeats a fixed number of times", "A condition-controlled (while / do…until) loop repeats until a condition is met, so the number of repeats may not be known in advance"], answer: "A count-controlled loop, such as a for loop, repeats a set number of times. A condition-controlled loop, such as a while loop, keeps repeating until a condition is met, so the number of repetitions may not be known in advance." },
      { g: 5, marks: 2, q: "State the output of this code:\nsubject = \"Computer\"\nprint(subject.length)\nprint(subject.left(3))", scheme: ["8", "Com"], answer: "The first line outputs 8 (there are 8 characters in \"Computer\") and the second outputs Com (the 3 leftmost characters)." },
      { g: 5, marks: 2, q: "Explain what is meant by authentication and give one example of how it is carried out.", scheme: ["Checking/confirming that a user is who they claim to be", "Example: username and password / PIN / fingerprint / two-factor authentication code"], answer: "Authentication is confirming that a user is who they claim to be before they are given access, for example by asking them to enter a username and password." },
      { g: 5, marks: 2, q: "A program accepts an age between 11 and 16 inclusive. Give one example of boundary test data and one example of erroneous test data.", scheme: ["Boundary: 11 or 16", "Erroneous: data of the wrong type, e.g. \"twelve\" or \"abc\""], answer: "Boundary data: 16 (or 11), which is on the edge of the valid range. Erroneous data: \"twelve\", which is the wrong data type and should be rejected." },
      { g: 5, marks: 2, q: "A truth table is drawn for an OR gate with two inputs, A and B. State how many rows of input combinations it has, and in how many of those rows the output is 1.", scheme: ["4 rows", "The output is 1 in 3 rows (every row except A = 0, B = 0)"], answer: "It has 4 rows (00, 01, 10 and 11). The output is 1 in 3 of them — every row except the one where A = 0 and B = 0." },
      { g: 5, marks: 2, q: "State two differences between a compiler and an interpreter.", scheme: ["A compiler translates the whole program in one go; an interpreter translates and runs the code one line at a time", "A compiler produces an executable file; an interpreter does not, so the code is translated every time it runs (also accept: a compiler reports errors after translating the whole program, an interpreter stops at the first error)"], answer: "A compiler translates the whole program at once, whereas an interpreter translates and runs it one line at a time. A compiler also produces an executable file that can run without the translator, whereas interpreted code has to be translated every time it is run." },
      { g: 5, marks: 1, q: "State the output of this code:\nfor i = 1 to 3\n    print(i * 2)\nnext i", scheme: ["2, 4, 6 (on separate lines)"], answer: "2, 4 and 6, each on a separate line." },
      { g: 5, marks: 2, q: "Give two reasons why programmers use subprograms.", scheme: ["Any one: code can be reused/called many times without being rewritten", "A second: easier to test and debug / easier to read and maintain / different programmers can work on different subprograms"], answer: "Subprograms can be called many times, so code does not need to be rewritten, and each one can be tested and debugged on its own, making the program easier to maintain." },
      { g: 5, marks: 2, q: "Explain the difference between iterative testing and final testing.", scheme: ["Iterative testing happens during development: each part/module is tested, fixed and retested as it is written", "Final (terminal) testing happens at the end: the whole completed program is tested to check it works as intended"], answer: "Iterative testing is carried out repeatedly during development, testing and fixing each part as it is written. Final testing happens once the program is complete, testing the whole program to check it meets its requirements." },
      { g: 5, marks: 3, q: "An algorithm calculates the area of a rectangle. Identify its inputs, its process and its output.", scheme: ["Inputs: the length and the width", "Process: multiply the length by the width", "Output: the area"], answer: "The inputs are the length and the width, the process is multiplying the length by the width, and the output is the area of the rectangle." },
      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 3, q: "Describe how a binary search finds an item in a sorted list.", scheme: ["The middle item is selected and compared with the target", "If it matches, the search stops; if the target is smaller the upper half is discarded, and if it is larger the lower half is discarded", "This repeats on the remaining items until the target is found or there are no items left"], answer: "A binary search compares the middle item of the list with the target. If they match, the search stops; if the target is smaller, the upper half is discarded, and if it is larger, the lower half is discarded. This repeats with the middle of the remaining items until the target is found or no items are left." },
      { g: 6, marks: 2, q: "A binary search is used to find 30 in the sorted list 3, 8, 12, 15, 21, 30, 42. State which items are compared with 30, in order, and what happens after each comparison.", scheme: ["15 is compared first (the middle item); 30 is greater than 15, so 3, 8, 12 and 15 are discarded", "30 is compared next (the middle of 21, 30, 42); it matches, so the search stops"], answer: "First the middle item, 15, is compared. As 30 is greater than 15, the lower half (3, 8, 12, 15) is discarded. The middle of the remaining items 21, 30, 42 is 30, which matches, so the search stops." },
      { g: 6, marks: 2, q: "Explain the difference between a local variable and a global variable.", scheme: ["A local variable is declared inside a subprogram and can only be accessed within that subprogram", "A global variable is declared in the main program and can be accessed anywhere in the program"], answer: "A local variable is declared inside a subprogram and only exists and can be used within that subprogram, whereas a global variable is declared in the main program and can be accessed from anywhere in the program." },
      { g: 6, marks: 3, q: "Explain what this SQL statement does:\nSELECT Name, Score FROM Results WHERE Score > 50", scheme: ["SELECT Name, Score: only the Name and Score fields are returned", "FROM Results: the data is taken from the table called Results", "WHERE Score > 50: only records with a score greater than 50 are returned"], answer: "It returns only the Name and Score fields, taken from the table called Results, for records where the Score is greater than 50." },
      { g: 6, marks: 2, q: "Explain two ways a programmer can make their code easier to maintain.", scheme: ["One technique explained, e.g. comments explain what sections of code do so other programmers can understand them", "A second technique explained, e.g. meaningful variable names make the purpose of data clear / indentation shows the structure / subprograms split code into manageable parts"], answer: "Adding comments explains what each section of code does, so other programmers can understand it. Using meaningful variable names, such as totalCost instead of x, makes the purpose of each variable clear." },
      { g: 6, marks: 2, q: "This code is meant to ask for a user's age and output their age next year:\nage = input(\"Enter your age\")\nprint(age + 1)\nExplain why the code will not work as intended and show how to fix it.", scheme: ["input() returns a string, and the integer 1 cannot be added to a string", "Cast the input to an integer, e.g. age = int(input(\"Enter your age\"))"], answer: "The input is stored as a string, so the program cannot add the integer 1 to it. The input should be cast to an integer: age = int(input(\"Enter your age\"))." },
      { g: 6, marks: 2, q: "A program should calculate the average of two numbers, a and b, but it uses this line:\naverage = a + b / 2\nIdentify the type of error and write the corrected line.", scheme: ["Logic error: division happens before addition, so only b is divided by 2", "average = (a + b) / 2"], answer: "It is a logic error — the program runs, but division is carried out before addition, so only b is halved. The corrected line is average = (a + b) / 2." },
      { g: 6, marks: 2, q: "A bubble sort is used to put the list 5, 2, 7, 1 into ascending order. State the swaps made during the first pass and the list after the first pass.", scheme: ["5 and 2 are swapped, then 7 and 1 are swapped (5 and 7 are not swapped)", "List after the first pass: 2, 5, 1, 7"], answer: "5 and 2 are compared and swapped, 5 and 7 are compared and not swapped, then 7 and 1 are compared and swapped. After the first pass the list is 2, 5, 1, 7." },
      { g: 6, marks: 3, q: "Describe how an insertion sort puts a list into ascending order.", scheme: ["The first item is treated as a sorted list of one item", "Each following item is taken in turn and compared with the items in the sorted part", "It is inserted into its correct position (larger items move up), repeating until every item has been inserted"], answer: "An insertion sort treats the first item as a sorted list. It then takes the next item and compares it with the items in the sorted part, moving larger items along and inserting it into the correct position. This repeats until every item has been inserted into the sorted part." },
      { g: 6, marks: 2, q: "A program stores a student's name, age and whether they have paid for a school trip. Explain why a record is more suitable than an array for storing this data.", scheme: ["The data items are of different data types (string, integer and Boolean)", "A record can store fields of different data types together, whereas an array stores values of a single data type"], answer: "The name is a string, the age is an integer and whether they have paid is a Boolean. A record can hold related fields of different data types together, whereas an array can only hold values of one data type." },
      { g: 6, marks: 2, q: "An alarm (Q) sounds only when the alarm system is switched on (A) and a door is open (B). Write this as a Boolean expression and state how many of the four possible input combinations make the alarm sound.", scheme: ["Q = A AND B", "1 combination (A = 1 and B = 1)"], answer: "Q = A AND B. Only one of the four combinations makes the alarm sound: when A = 1 and B = 1." },
      { g: 6, marks: 2, q: "Explain two advantages of writing a program in a high-level language rather than a low-level language.", scheme: ["It is closer to English, so it is easier to read, write and debug (programs are quicker to develop)", "It is portable: it can be translated to run on different types of processor"], answer: "High-level languages are closer to English, so programs are quicker to write and easier to read and debug. They are also portable, so the same program can be translated to run on different types of processor." },
      { g: 6, marks: 3, q: "Write OCR Exam Reference Language code to open a file called scores.txt, read the first line into a variable called firstScore, and then close the file.", scheme: ["Opens the file, e.g. myFile = open(\"scores.txt\")", "Reads a line into the variable, e.g. firstScore = myFile.readLine()", "Closes the file, e.g. myFile.close()"], answer: "myFile = open(\"scores.txt\")\nfirstScore = myFile.readLine()\nmyFile.close()" },
      { g: 6, marks: 2, q: "Write one line of OCR Exam Reference Language that simulates rolling a six-sided dice and stores the result in a variable called roll. Then explain why random numbers are useful in games.", scheme: ["roll = random(1, 6)", "They make the game unpredictable, so the outcome can be different each time it is played"], answer: "roll = random(1, 6). Random numbers make games unpredictable, so events such as dice rolls give a different outcome each time the game is played." },
      { g: 6, marks: 2, q: "A teacher wants to store the scores of 30 students in 3 tests. Explain why a 2D array is suitable and write a declaration for it.", scheme: ["The data forms a table: one row per student and one column per test, all of the same data type", "array scores[30, 3]"], answer: "The data is a table of values of the same type, with a row for each student and a column for each test, which is exactly what a 2D array stores. It could be declared as array scores[30, 3]." },
      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "A trace table with columns i and total is used to follow this algorithm:\ntotal = 0\nfor i = 1 to 4\n    total = total + i * 2\nnext i\nprint(total)\nState the value of total after each iteration of the loop, and the final output.", scheme: ["total = 2 when i = 1, and 6 when i = 2", "total = 12 when i = 3, and 20 when i = 4", "Output: 20"], answer: "When i = 1, total = 2; when i = 2, total = 6; when i = 3, total = 12; when i = 4, total = 20. The loop then ends and the program outputs 20." },
      { g: 7, marks: 3, q: "Show the stages of a merge sort being used to sort the list 6, 3, 8, 1 into ascending order.", scheme: ["The list is split into halves: [6, 3] and [8, 1]", "These are split into single items: [6] [3] [8] [1]", "Items are merged back in order: [3, 6] and [1, 8], then [1, 3, 6, 8]"], answer: "Split the list into [6, 3] and [8, 1], then into single items [6] [3] [8] [1]. Merge pairs in order to give [3, 6] and [1, 8], then merge these to give [1, 3, 6, 8]." },
      { g: 7, marks: 4, q: "Write an algorithm that asks the user to enter five whole numbers and then outputs their total.", scheme: ["total is set to 0 before the loop", "A loop that repeats exactly 5 times", "Each number is input, cast to an integer and added to total inside the loop", "total is output after the loop has finished"], answer: "total = 0\nfor i = 1 to 5\n    num = int(input(\"Enter a whole number\"))\n    total = total + num\nnext i\nprint(total)" },
      { g: 7, marks: 3, q: "A sorted list contains 1000 items. Explain why a binary search is usually much faster than a linear search for finding an item in this list.", scheme: ["A linear search checks items one at a time, so it may need up to 1000 comparisons", "A binary search discards half of the remaining items after each comparison", "So it needs at most about 10 comparisons (1000 → 500 → 250 → …)"], answer: "A linear search checks each item in turn, so in the worst case it makes 1000 comparisons. A binary search halves the number of remaining items with every comparison (1000, 500, 250, 125 …), so it needs at most about 10 comparisons." },
      { g: 7, marks: 3, q: "Write an algorithm that asks a user to create a password and keeps asking until the password entered is at least 8 characters long. It should then output \"Password accepted\".", scheme: ["The password is input", "A loop repeats while password.length < 8, with the password input again inside the loop", "\"Password accepted\" is output only after the loop ends"], answer: "password = input(\"Create a password\")\nwhile password.length < 8\n    print(\"Password must be at least 8 characters\")\n    password = input(\"Create a password\")\nendwhile\nprint(\"Password accepted\")" },
      { g: 7, marks: 3, q: "Strings are indexed from 0, and substring(x, n) returns n characters starting at index x. State the output of each print statement:\nword = \"ALGORITHM\"\nprint(word.length)\nprint(word.substring(2, 3))\nprint(word.right(3))", scheme: ["9", "GOR", "THM"], answer: "word.length outputs 9. word.substring(2, 3) starts at index 2 (G) and takes 3 characters, giving GOR. word.right(3) gives the last three characters, THM." },
      { g: 7, marks: 3, q: "Write a function called isEven that takes a whole number as a parameter and returns true if the number is even and false if it is odd.", scheme: ["Function defined with a parameter, e.g. function isEven(num) … endfunction", "Uses num MOD 2 == 0 to test whether the number is even", "Returns true when even and false when odd"], answer: "function isEven(num)\n    if num MOD 2 == 0 then\n        return true\n    else\n        return false\n    endif\nendfunction" },
      { g: 7, marks: 3, q: "For the Boolean expression Q = (A AND B) OR C, state the value of Q for each set of inputs:\n(i) A = 1, B = 0, C = 0\n(ii) A = 1, B = 1, C = 0\n(iii) A = 0, B = 0, C = 1", scheme: ["(i) Q = 0", "(ii) Q = 1", "(iii) Q = 1"], answer: "(i) 1 AND 0 = 0, and 0 OR 0 = 0, so Q = 0. (ii) 1 AND 1 = 1, and 1 OR 0 = 1, so Q = 1. (iii) 0 AND 0 = 0, and 0 OR 1 = 1, so Q = 1." },
      { g: 7, marks: 3, q: "A 2D array called temps stores temperatures. The first index is the row and the second is the column, both starting at 0. Row 0 holds 12, 15, 11; row 1 holds 14, 9, 16; row 2 holds 10, 13, 17.\nState the values of temps[1, 2] and temps[2, 0], then write code to output every value in row 0.", scheme: ["temps[1, 2] = 16", "temps[2, 0] = 10", "A loop through columns 0 to 2 outputting temps[0, col]"], answer: "temps[1, 2] = 16 and temps[2, 0] = 10.\nfor col = 0 to 2\n    print(temps[0, col])\nnext col" },
      { g: 7, marks: 4, q: "A program accepts the number of goals scored in a football match as a whole number from 0 to 20 inclusive. Give one example each of normal, boundary, invalid and erroneous test data, stating whether each should be accepted or rejected.", scheme: ["Normal: e.g. 3 — accepted", "Boundary: 0 or 20 — accepted", "Invalid: e.g. 25 or -1 — rejected", "Erroneous: e.g. \"five\" — rejected (wrong data type)"], answer: "Normal: 3, which should be accepted. Boundary: 20 (or 0), which should be accepted. Invalid: 25, which is the right type but outside the range, so it should be rejected. Erroneous: \"five\", which is the wrong data type, so it should be rejected." },
      { g: 7, marks: 4, q: "A programmer is writing a game that will be sold to customers. Explain why they might use an interpreter while developing the game but a compiler to produce the final version.", scheme: ["An interpreter runs the code line by line and stops at the line containing an error, making errors easier to find", "Code can be run and tested straight away without translating the whole program each time", "A compiler produces an executable file that runs quickly and does not need a translator on the customer's computer", "Customers receive the executable rather than the source code, so the code cannot easily be copied or changed"], answer: "During development an interpreter is useful because it translates and runs the code line by line, stopping at the line with an error, and code can be tested straight away. For the final version a compiler produces an executable file that runs quickly without customers needing a translator, and because customers do not receive the source code, it cannot easily be copied or altered." },
      { g: 7, marks: 4, q: "Explain how abstraction and decomposition could be used when designing a program to manage a school library.", scheme: ["Abstraction: removing unnecessary details and focusing only on what the program needs", "Example: storing only relevant book details such as title, author, ISBN and loan status (not the cover colour)", "Decomposition: breaking the problem into smaller sub-problems that can be solved separately", "Example: separate parts for adding books, lending and returning books, searching the catalogue and calculating late fines"], answer: "Abstraction would remove unnecessary details, so the program only stores what it needs about each book, such as the title, author, ISBN and whether it is on loan, not the colour of its cover. Decomposition would break the system into smaller sub-problems — adding books, lending and returning books, searching the catalogue and calculating late fines — which can each be designed and coded separately." },
      { g: 7, marks: 3, q: "Look at this function:\nfunction discount(price, percent)\n    saving = price * percent / 100\n    return price - saving\nendfunction\nState the output of print(discount(80, 25)), and identify one parameter and one local variable in the function.", scheme: ["60", "Parameter: price or percent", "Local variable: saving"], answer: "saving = 80 × 25 ÷ 100 = 20, so the function returns 80 − 20 and the output is 60. price (or percent) is a parameter, and saving is a local variable." },
      { g: 7, marks: 4, q: "An array called names holds three names at indexes 0 to 2. Write OCR Exam Reference Language code that writes each name on a separate line of a new file called names.txt.", scheme: ["Creates/opens the file names.txt", "A loop that runs for indexes 0 to 2", "Writes names[i] to the file with writeLine inside the loop", "Closes the file after the loop"], answer: "newFile(\"names.txt\")\nmyFile = open(\"names.txt\")\nfor i = 0 to 2\n    myFile.writeLine(names[i])\nnext i\nmyFile.close()" },
      { g: 7, marks: 3, q: "An insertion sort is used to put the list 4, 1, 3, 2 into ascending order. State the list after each item is inserted into the sorted part.", scheme: ["After inserting 1: 1, 4, 3, 2", "After inserting 3: 1, 3, 4, 2", "After inserting 2: 1, 2, 3, 4"], answer: "4 starts as the sorted part. Inserting 1 gives 1, 4, 3, 2. Inserting 3 gives 1, 3, 4, 2. Inserting 2 gives 1, 2, 3, 4." },
      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Trace this algorithm, stating the values of total and num after each iteration of the loop, and the final output:\nnum = 347\ntotal = 0\nwhile num > 0\n    total = total + num MOD 10\n    num = num DIV 10\nendwhile\nprint(total)", scheme: ["After iteration 1: total = 7, num = 34", "After iteration 2: total = 11, num = 3", "After iteration 3: total = 14, num = 0", "The loop stops because num is no longer greater than 0; output is 14 (the sum of the digits)"], answer: "Iteration 1: 347 MOD 10 = 7, so total = 7, and num = 347 DIV 10 = 34. Iteration 2: total = 7 + 4 = 11, num = 3. Iteration 3: total = 11 + 3 = 14, num = 0. The condition num > 0 is now false, so the loop stops and 14 is output — the sum of the digits of 347." },
      { g: 8, marks: 4, q: "A bubble sort is used to sort the list 9, 4, 7, 2, 5 into ascending order. State the list after each pass and explain when the algorithm stops.", scheme: ["After pass 1: 4, 7, 2, 5, 9", "After pass 2: 4, 2, 5, 7, 9", "After pass 3: 2, 4, 5, 7, 9", "Pass 4 makes no swaps, so the algorithm stops"], answer: "After pass 1 the list is 4, 7, 2, 5, 9 (9 has moved to the end). After pass 2 it is 4, 2, 5, 7, 9. After pass 3 it is 2, 4, 5, 7, 9. A fourth pass is made with no swaps, which shows the list is sorted, so the algorithm stops." },
      { g: 8, marks: 5, q: "An array called names stores 10 names at indexes 0 to 9. Write an algorithm that asks the user for a name, performs a linear search, and outputs the index where the name is found or \"Not found\" if it is not in the array.", scheme: ["The name to search for is input", "A loop that goes through indexes 0 to 9", "Each names[i] is compared with the name entered", "The index is output when a match is found", "\"Not found\" is output (once) only if no match is found, e.g. using a Boolean flag"], answer: "target = input(\"Enter a name\")\nfound = false\nfor i = 0 to 9\n    if names[i] == target then\n        print(\"Found at index \" + str(i))\n        found = true\n    endif\nnext i\nif found == false then\n    print(\"Not found\")\nendif" },
      { g: 8, marks: 3, q: "A binary search is used to find 9 in the sorted list 2, 5, 9, 13, 18, 24, 31, 40, 47 (indexes 0 to 8). The middle index is calculated as (low + high) DIV 2. State each item compared and how low or high changes after each comparison.", scheme: ["low = 0, high = 8, mid = 4: 18 is compared; 9 < 18 so high becomes 3", "mid = (0 + 3) DIV 2 = 1: 5 is compared; 9 > 5 so low becomes 2", "mid = (2 + 3) DIV 2 = 2: 9 is compared and found at index 2"], answer: "First mid = (0 + 8) DIV 2 = 4, so 18 is compared; 9 is smaller, so high = 3. Next mid = (0 + 3) DIV 2 = 1, so 5 is compared; 9 is larger, so low = 2. Then mid = (2 + 3) DIV 2 = 2, so 9 is compared and found at index 2." },
      { g: 8, marks: 3, q: "A table called Students has the fields StudentID, FirstName, Surname, Form and Age. Write an SQL statement that returns the first name and surname of every student in form 11B who is aged 16 or over.", scheme: ["SELECT FirstName, Surname", "FROM Students", "WHERE Form = \"11B\" AND Age >= 16"], answer: "SELECT FirstName, Surname\nFROM Students\nWHERE Form = \"11B\" AND Age >= 16" },
      { g: 8, marks: 4, q: "This program should output the largest of five numbers entered:\nlargest = 0\nfor i = 1 to 5\n    num = int(input(\"Enter a number\"))\n    if num < largest then\n        largest = num\n    endif\nnext i\nprint(largest)\nWhen tested with 4, 9, 2, 7 and 5 it outputs 0. Identify the type of error, explain why it outputs 0, and describe how to correct the program so it also works when every number entered is negative.", scheme: ["It is a logic error: the program runs but produces the wrong output", "num < largest is never true for positive numbers, so largest is never updated and stays 0", "The comparison should be changed to num > largest", "largest should start as the first number entered (e.g. input one number before the loop and loop 4 more times), so negative numbers are handled"], answer: "It is a logic error, because the program runs but gives the wrong result. None of the positive numbers are less than 0, so largest is never changed and stays at 0. The condition should be num > largest. Starting largest at 0 would also fail if all the numbers were negative, so largest should be set to the first number entered, with the loop then running for the remaining 4 numbers." },
      { g: 8, marks: 4, q: "A heating system (H) switches on when it is cold (C) and the house is occupied (O), or when the frost-protection switch (F) is on. Write a Boolean expression for H, then state the value of H for each set of inputs:\n(i) C = 0, O = 1, F = 0\n(ii) C = 1, O = 1, F = 0\n(iii) C = 0, O = 0, F = 1", scheme: ["H = (C AND O) OR F", "(i) H = 0", "(ii) H = 1", "(iii) H = 1"], answer: "H = (C AND O) OR F. (i) 0 AND 1 = 0, and 0 OR 0 = 0, so H = 0. (ii) 1 AND 1 = 1, so H = 1. (iii) 0 AND 0 = 0, but F = 1, so H = 1." },
      { g: 8, marks: 4, q: "State the output of each print statement:\na = \"5\"\nb = 3\nprint(a + str(b))\nprint(int(a) + b)\nprint(int(a) MOD b)\nprint(str(b * 2) + a)", scheme: ["53", "8", "2", "65"], answer: "a + str(b) joins two strings, giving 53. int(a) + b adds two integers, giving 8. int(a) MOD b = 5 MOD 3 = 2. str(b * 2) is \"6\", which is joined with \"5\" to give 65." },
      { g: 8, marks: 4, q: "Write a function called rollDice that takes the number of six-sided dice to roll as a parameter and returns the total score of all the dice.", scheme: ["Function defined with a parameter, e.g. function rollDice(numDice) … endfunction", "A running total set to 0 and a loop that repeats numDice times", "random(1, 6) generated and added to the total inside the loop", "The total is returned after the loop"], answer: "function rollDice(numDice)\n    total = 0\n    for i = 1 to numDice\n        total = total + random(1, 6)\n    next i\n    return total\nendfunction" },
      { g: 8, marks: 3, q: "Explain how the editor, error diagnostics and run-time environment of an IDE each help a programmer to develop a working program.", scheme: ["Editor: lets code be written and edited, with features such as syntax highlighting, auto-indentation and auto-completion that reduce mistakes", "Error diagnostics: report errors (often with line numbers) and provide debugging tools such as breakpoints and stepping through code to locate problems", "Run-time environment: allows the program to be run and tested within the IDE, showing its output and any errors that occur while it runs"], answer: "The editor lets the programmer write code with features like syntax highlighting and auto-indentation, which make mistakes easier to spot. Error diagnostics report errors with line numbers and provide tools such as breakpoints and stepping through code to find where problems occur. The run-time environment lets the programmer run and test the program inside the IDE, seeing its output and any errors as it runs." },
      { g: 8, marks: 5, q: "Write an algorithm that gives a user up to three attempts to enter the correct password, \"Secret1\". It should output \"Welcome\" if the correct password is entered, or \"Locked\" after three incorrect attempts.", scheme: ["An attempts counter set to 0 (and a flag such as correct = false)", "A loop that continues while attempts < 3 and the correct password has not been entered", "The password is input inside the loop and compared with \"Secret1\"", "The attempts counter is increased after an incorrect password", "\"Welcome\" output if correct, otherwise \"Locked\" after three failures"], answer: "attempts = 0\ncorrect = false\nwhile attempts < 3 AND correct == false\n    password = input(\"Enter password\")\n    if password == \"Secret1\" then\n        correct = true\n    else\n        attempts = attempts + 1\n    endif\nendwhile\nif correct == true then\n    print(\"Welcome\")\nelse\n    print(\"Locked\")\nendif" },
      { g: 8, marks: 4, q: "Describe the stages of a merge sort being used to sort the list 38, 27, 43, 3, 9, 82, 10, 5 into ascending order.", scheme: ["The list is split repeatedly in half until there are 8 single items", "Single items are merged into sorted pairs: [27, 38], [3, 43], [9, 82], [5, 10]", "Pairs are merged into sorted lists of four: [3, 27, 38, 43] and [5, 9, 10, 82]", "The final merge gives [3, 5, 9, 10, 27, 38, 43, 82]"], answer: "The list is split in half repeatedly until there are eight single items. These are merged into sorted pairs: [27, 38], [3, 43], [9, 82] and [5, 10]. The pairs are merged into [3, 27, 38, 43] and [5, 9, 10, 82], and a final merge gives [3, 5, 9, 10, 27, 38, 43, 82]." },
      { g: 8, marks: 4, q: "A 2D array called sales stores the daily sales of 4 shops over 7 days. The first index is the shop (0 to 3) and the second is the day (0 to 6). Write an algorithm that calculates and outputs the total sales for all shops over all days.", scheme: ["A total variable set to 0 before the loops", "An outer loop for shops 0 to 3", "A nested inner loop for days 0 to 6 that adds sales[shop, day] to the total", "The total is output after both loops have finished"], answer: "total = 0\nfor shop = 0 to 3\n    for day = 0 to 6\n        total = total + sales[shop, day]\n    next day\nnext shop\nprint(total)" },
      { g: 8, marks: 4, q: "The variables firstName and surname hold strings, and yearJoined holds an integer such as 2025. Write code that creates a username made of the first three letters of the surname, followed by the first letter of the first name, followed by the year joined, and then outputs it. For example, Jo Smith who joined in 2025 would get SmiJ2025.", scheme: ["Takes the first three letters of the surname, e.g. surname.left(3) or surname.substring(0, 3)", "Takes the first letter of the first name, e.g. firstName.left(1)", "Casts yearJoined to a string using str(yearJoined)", "Concatenates the parts in the correct order and outputs the username"], answer: "username = surname.left(3) + firstName.left(1) + str(yearJoined)\nprint(username)" },
      { g: 8, marks: 4, q: "Look at this code:\nx = float(input(\"Enter price\"))\ny = x * 0.2\nprint(x + y)\nIt adds VAT at 20% to a price. Explain three ways the code could be made easier to maintain, and rewrite it using your improvements.", scheme: ["Use meaningful identifiers, e.g. price and vat instead of x and y, so the purpose of each variable is clear", "Store 0.2 as a constant (e.g. const VAT_RATE = 0.2) so it only needs changing in one place if the rate changes", "Add comments to explain what the code does", "Rewritten code that uses these improvements and still works correctly"], answer: "Meaningful names make the purpose of each variable clear, a constant for the VAT rate means it only has to be changed in one place, and comments explain the code to other programmers.\n// Adds VAT to a price entered by the user\nconst VAT_RATE = 0.2\nprice = float(input(\"Enter price\"))\nvat = price * VAT_RATE\nprint(price + vat)" },
      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Compare bubble sort, insertion sort and merge sort, and evaluate which would be most suitable for (a) sorting a list of one million customer records and (b) sorting a list of 20 items that is already nearly in order.", scheme: ["Bubble sort: simple to code, but makes many passes and comparisons, so it is very slow for large lists", "Insertion sort: simple and sorts in place (little extra memory); fast for small or nearly sorted lists, but slow for large unsorted lists", "Merge sort: splits and merges, so it is much faster/more efficient for large lists", "Merge sort drawback: uses more memory because it creates extra lists, and is more complex to code", "(a) Merge sort is best for one million records because of its speed on large data sets", "(b) Insertion sort is best for 20 nearly sorted items: few items need moving, it is simple and uses little memory"], answer: "A bubble sort is simple but makes many passes, comparing and swapping adjacent items, so it is very slow on large lists. An insertion sort is also simple and sorts in place using little memory; it is quick when a list is small or nearly sorted but slow on large unsorted lists. A merge sort repeatedly splits and merges the list, making it far more efficient for large lists, although it uses more memory for the extra lists and is harder to code. For one million records, merge sort is the best choice because speed matters most. For 20 nearly sorted items, insertion sort is best, as very few items need moving, it is easy to implement and it needs no extra memory." },
      { g: 9, marks: 6, q: "An online shop has an unsorted list of 50,000 products, and customers search it thousands of times a day. Evaluate whether it is better to use a linear search every time, or to sort the list once with a merge sort and then use a binary search.", scheme: ["Linear search works on the unsorted list with no preparation needed", "But each linear search may need up to 50,000 comparisons, which is slow when repeated thousands of times", "A merge sort must be done first, which takes time and extra memory, and the list must be kept sorted when products are added", "Binary search halves the remaining items each comparison, so it needs at most about 16 comparisons for 50,000 items", "The one-off cost of sorting is quickly outweighed by thousands of fast searches", "Justified conclusion: sort once and use binary search"], answer: "A linear search needs no preparation because it works on the unsorted list, but each search may make up to 50,000 comparisons, which adds up to a huge amount of processing over thousands of searches. Sorting with a merge sort first costs time and memory, and new products must be inserted in the correct place to keep the list sorted. However, a binary search then halves the remaining items with every comparison, so it needs at most about 16 comparisons. Because the list is searched so often, the one-off cost of sorting is quickly outweighed by much faster searches, so sorting once and using binary search is the better approach." },
      { g: 9, marks: 6, q: "A file called scores.txt contains at least one line, and each line holds a whole-number score from 0 to 100. Write an algorithm that reads every score from the file, then outputs the average score and the highest score.", scheme: ["Opens scores.txt and closes it after reading", "A loop that repeats until the end of the file is reached, e.g. while NOT myFile.endOfFile()", "Each line is read with readLine() and cast to an integer", "A running total and a count are updated for each score", "The highest score is updated when a score is greater than the current highest", "The average (total / count) and the highest score are output after the loop"], answer: "myFile = open(\"scores.txt\")\ntotal = 0\ncount = 0\nhighest = 0\nwhile NOT myFile.endOfFile()\n    score = int(myFile.readLine())\n    total = total + score\n    count = count + 1\n    if score > highest then\n        highest = score\n    endif\nendwhile\nmyFile.close()\nprint(\"Average: \" + str(total / count))\nprint(\"Highest: \" + str(highest))" },
      { g: 9, marks: 5, q: "This code is meant to accept only a mark from 0 to 100:\nmark = int(input(\"Enter mark\"))\nif mark >= 0 OR mark <= 100 then\n    print(\"Valid\")\nendif\nEvaluate how well the code validates the input, then write an improved version that keeps asking until a valid mark is entered.", scheme: ["Identifies that OR makes the condition true for every whole number (e.g. 150 is still ≥ 0), so invalid marks are accepted", "A correct range check, e.g. AND in the if, or looping while mark < 0 OR mark > 100", "The mark is input again inside a loop until it is valid", "An error message is shown when the mark is invalid", "Notes a remaining weakness: non-numeric input would still cause a crash when cast with int(), so a type check would also be needed"], answer: "The condition uses OR, so any whole number passes — 150 is greater than or equal to 0, and -5 is less than or equal to 100 — meaning the check does nothing. The program also gives no error message and does not ask again. An improved version:\nmark = int(input(\"Enter mark\"))\nwhile mark < 0 OR mark > 100\n    print(\"Mark must be between 0 and 100\")\n    mark = int(input(\"Enter mark\"))\nendwhile\nprint(\"Valid\")\nThis still crashes if letters are entered, because int() cannot convert them, so a type check would also be needed to make it fully robust." },
      { g: 9, marks: 5, q: "A developer is writing (a) a large mobile banking app and (b) a very small program to control a sensor in an embedded device with very little memory. Evaluate the use of high-level and low-level languages for each, making a justified recommendation.", scheme: ["High-level: closer to English, so quicker to write, read, debug and maintain, which suits a large team project", "High-level: portable across different processors, but must be translated and gives less direct control of hardware (code may be less efficient)", "Low-level: gives direct control of the hardware and produces very efficient code that uses little memory", "Low-level: hard to write and debug, and specific to one type of processor", "Justified recommendation: high-level for the banking app; low-level (e.g. assembly) could suit the small embedded program where memory and efficiency are critical"], answer: "High-level languages are close to English, so they are quicker to write, easier to debug and easier for a team to maintain, and they are portable across different processors; however, they must be translated and give less direct control over hardware. Low-level languages give direct control of the hardware and produce very efficient code that uses little memory, but they are difficult to write and debug and only work on one type of processor. The large banking app should use a high-level language because development speed and maintainability matter most. The small sensor program could be written in a low-level language such as assembly, because memory is very limited and the code is small enough to write that way." },
      { g: 9, marks: 5, q: "Evaluate whether (a) students learning to program for the first time and (b) a company releasing a commercial game should use a compiler or an interpreter.", scheme: ["Interpreter: translates and runs line by line, stopping at the line with an error, so errors are easy to find and code can be tested immediately", "Interpreter drawback: runs more slowly, and the source code and an interpreter are needed every time it runs", "Compiler: translates the whole program into an executable that runs quickly without needing a translator", "Compiler: the source code is not given to users so it is protected, but errors are reported only after translating the whole program and it must be recompiled after every change", "Justified conclusion: interpreter for beginners (immediate feedback); compiler for the commercial game (speed, no translator needed, protected code)"], answer: "An interpreter translates and runs code one line at a time and stops at the line containing an error, so problems are easy to locate and code can be tested straight away; however, interpreted programs run more slowly and need the source code and interpreter every time. A compiler turns the whole program into an executable file that runs quickly without a translator and keeps the source code private, but it reports errors only after translating everything and must recompile after each change. Beginners benefit most from an interpreter because of its immediate, line-by-line feedback. The company should use a compiler for its release, as players need a fast game that runs without a translator and the company wants to protect its code." },
      { g: 9, marks: 6, q: "A cinema program calculates the cost of an order. The user enters the number of tickets, which must be a whole number from 1 to 8. Explain a thorough testing strategy for this program, including the types of testing and suitable test data with expected results.", scheme: ["Iterative testing: each part (e.g. the ticket input validation and the price calculation) is tested and fixed repeatedly during development", "Final/terminal testing: the complete program is tested at the end to check it meets the requirements", "A test plan records the test data, expected result and actual result, and failed tests are fixed and retested", "Normal data, e.g. 4 tickets — accepted and correct cost calculated", "Boundary data, e.g. 1 and 8 — accepted (0 or 9 just outside the range — rejected)", "Invalid data, e.g. 12, and erroneous data, e.g. \"two\" — both rejected with an error message"], answer: "The programmer should use iterative testing during development, testing each part — such as the ticket validation and the price calculation — as it is written and fixing problems before moving on. Final testing should then check the whole program works as required. A test plan should list each test, its data, the expected result and the actual result, with any failures fixed and retested. Test data should include normal data such as 4 tickets, which should be accepted with the correct cost; boundary data of 1 and 8, which should be accepted, with 0 and 9 rejected; invalid data such as 12, which should be rejected; and erroneous data such as \"two\", which should be rejected with a suitable error message." },
      { g: 9, marks: 5, q: "A team of programmers is building a large program. Evaluate the use of subprograms with parameters and local variables compared with writing one long program that uses global variables.", scheme: ["Subprograms split the problem into parts, so different programmers can work on different subprograms at the same time", "Subprograms can be reused and each tested on its own, making debugging and maintenance easier", "Parameters pass data into subprograms, so they are self-contained and can be used with different values", "Local variables only exist inside their subprogram, so they cannot be accidentally changed elsewhere and names can be reused without clashes; global variables can be changed anywhere, making errors hard to trace", "Justified conclusion: subprograms with parameters and local variables are better for a large team (globals only for values genuinely needed throughout, e.g. constants)"], answer: "Splitting the program into subprograms lets different team members work on separate parts at the same time, and each subprogram can be reused and tested independently, which makes debugging and maintenance easier. Parameters pass data in, so each subprogram is self-contained and works with different values. Local variables only exist within their subprogram, so other code cannot accidentally change them and the same names can be reused safely, whereas global variables can be altered from anywhere, making errors hard to trace. A single long program with globals may be quicker to start but becomes very hard to manage, so subprograms with parameters and local variables are the better choice for a large team, using globals only for values needed everywhere, such as constants." },
      { g: 9, marks: 5, q: "A car's warning light (W) comes on when the engine is running (E = 1) and either the seatbelt is not fastened or a door is open. S = 1 means the seatbelt is fastened and D = 1 means a door is open. Write a Boolean expression for W, then state the value of W for each combination of S and D when E = 1.", scheme: ["W = E AND (NOT S OR D)", "S = 0, D = 0: W = 1", "S = 0, D = 1: W = 1", "S = 1, D = 0: W = 0", "S = 1, D = 1: W = 1"], answer: "W = E AND (NOT S OR D). With E = 1: when S = 0 and D = 0, NOT S = 1 so W = 1; when S = 0 and D = 1, W = 1; when S = 1 and D = 0, NOT S = 0 and D = 0, so W = 0; when S = 1 and D = 1, the open door makes W = 1." },
      { g: 9, marks: 5, q: "A noughts and crosses game stores its board in a 2D array called grid, where grid[row, col] holds \"X\", \"O\" or \"\" and rows and columns are numbered 0 to 2. Write a function called checkRow that takes the grid, a row number and a symbol as parameters, and returns true if all three squares in that row contain the symbol, or false otherwise.", scheme: ["Function defined with three parameters, e.g. function checkRow(grid, row, symbol) … endfunction", "Loops through columns 0 to 2 of the given row (or checks all three squares)", "Compares each grid[row, col] with symbol", "Returns false as soon as a square does not match", "Returns true only if all three squares match"], answer: "function checkRow(grid, row, symbol)\n    for col = 0 to 2\n        if grid[row, col] != symbol then\n            return false\n        endif\n    next col\n    return true\nendfunction" },
      { g: 9, marks: 6, q: "Explain how abstraction, decomposition and algorithmic thinking would each be used to develop a sat nav program that finds the quickest route between two places.", scheme: ["Abstraction: removes unnecessary detail and keeps only what matters for routes", "Example: the map is represented as roads/junctions with distances, speed limits and traffic, ignoring details such as buildings or scenery", "Decomposition: breaks the problem into smaller sub-problems", "Example: sub-problems such as entering the destination, finding the current location, calculating the route, and giving directions", "Algorithmic thinking: working out the ordered steps (the algorithm) to solve each sub-problem", "Example: steps to compare possible routes and choose the one with the shortest journey time, recalculating if a turn is missed"], answer: "Abstraction removes detail that is not needed, so the map is represented simply as roads and junctions with distances, speed limits and traffic levels, ignoring things like buildings and scenery. Decomposition breaks the program into smaller problems, such as entering the destination, finding the current location, calculating the route and giving spoken directions, which can be solved separately. Algorithmic thinking is then used to design the ordered steps for each part — for example, an algorithm that compares possible routes using distance and speed to choose the one with the shortest journey time, and recalculates if the driver misses a turn." },
      { g: 9, marks: 6, q: "A program stores the title, release year and rating out of 10 for 200 films. Compare storing this data in a 2D array with storing it as records, and write an SQL statement to return the titles of films with a rating above 8 from a table called Films with fields Title, Year and Rating.", scheme: ["A 2D array can only hold one data type, so the year and rating would have to be stored as strings and cast before calculations", "Records allow each field to have its own data type (string, integer, real)", "Record fields are accessed by name (e.g. film.Title), which is clearer and easier to maintain than remembering column numbers", "Justified conclusion: records are more suitable for this data", "SELECT Title FROM Films", "WHERE Rating > 8"], answer: "A 2D array could hold the films as rows, but every value must be the same data type, so the years and ratings would be stored as strings and need casting before any calculations. Records allow each field to have its own data type — a string title, an integer year and a real rating — and fields are accessed by name, such as film.Title, which is clearer than remembering which column holds what. Records are therefore more suitable. The SQL statement is:\nSELECT Title FROM Films WHERE Rating > 8" },
      { g: 9, marks: 5, q: "Look at this function:\nfunction mystery(n)\n    result = 1\n    while n > 1\n        result = result * n\n        n = n - 1\n    endwhile\n    return result\nendfunction\nTrace print(mystery(4)), stating result and n after each iteration. State the purpose of the function and explain one problem with the values it accepts.", scheme: ["After iteration 1: result = 4, n = 3", "After iteration 2: result = 12, n = 2", "After iteration 3: result = 24, n = 1; the loop ends and 24 is output", "Purpose: it calculates the factorial of n (n × (n − 1) × … × 1)", "Problem: a negative number returns 1, which is wrong, so n should be validated to be 0 or more"], answer: "Iteration 1: result = 1 × 4 = 4, n = 3. Iteration 2: result = 4 × 3 = 12, n = 2. Iteration 3: result = 12 × 2 = 24, n = 1. Now n > 1 is false, so the function returns 24, which is printed. The function calculates the factorial of n. However, if a negative number is passed in, the loop never runs and it returns 1, which is incorrect, so the input should be validated to make sure n is 0 or greater." },
      { g: 9, marks: 6, q: "Write an algorithm for a guessing game. The computer picks a random whole number from 1 to 100. The user keeps guessing; after each wrong guess the program outputs \"Higher\" or \"Lower\". When the user guesses correctly, the program outputs how many guesses they took.", scheme: ["A random number from 1 to 100 is generated, e.g. target = random(1, 100)", "A guess counter is set to 0 before the loop", "A condition-controlled loop repeats until the guess equals the target", "Each guess is input and cast to an integer, and the counter increases by 1", "Outputs \"Higher\" if the guess is too low and \"Lower\" if it is too high", "The number of guesses is output after the loop ends"], answer: "target = random(1, 100)\nguesses = 0\nguess = 0\nwhile guess != target\n    guess = int(input(\"Enter your guess\"))\n    guesses = guesses + 1\n    if guess < target then\n        print(\"Higher\")\n    elseif guess > target then\n        print(\"Lower\")\n    endif\nendwhile\nprint(\"Correct! You took \" + str(guesses) + \" guesses\")" },
      { g: 9, marks: 6, q: "An array called numbers holds 8 integers at indexes 0 to 7. Write an algorithm that uses a bubble sort to put the array into ascending order, stopping as soon as a pass is made with no swaps.", scheme: ["An outer loop that repeats while a swap was made in the previous pass", "A swapped flag set to false at the start of each pass", "An inner loop that compares adjacent items, with i from 0 to 6 so numbers[i + 1] stays within the array", "The condition numbers[i] > numbers[i + 1]", "The two items are swapped using a temporary variable", "swapped is set to true whenever a swap happens, so the algorithm stops after a pass with no swaps"], answer: "swapped = true\nwhile swapped == true\n    swapped = false\n    for i = 0 to 6\n        if numbers[i] > numbers[i + 1] then\n            temp = numbers[i]\n            numbers[i] = numbers[i + 1]\n            numbers[i + 1] = temp\n            swapped = true\n        endif\n    next i\nendwhile" },
    ],
  },
}
